---
title: Order processing contracts
---
classDiagram
  direction LR
  namespace Commerce {
    namespace Domain {
      class Entity {
        <<abstract>>
        #id : UUID
        +validate()*
      }
      class Order {
        -items : List~LineItem~
        +total : Decimal
        +add(item LineItem)
        +validate() bool
      }
      class LineItem {
        +quantity : int
        -unitPrice : Decimal
        +subtotal() Decimal
      }
      class Status {
        <<enumeration>>
        PENDING
        PAID
        CANCELLED
      }
    }
    namespace Application {
      class Repository~T~ {
        <<interface>>
        +findById(id UUID) T
        +matrix() List~List~T~~
        +save(value T)
      }
      class OrderRepository {
        -cache : List~List~Order~~
        +findById(id UUID) Order
        +save(value Order)
      }
      class CheckoutService {
        -repository : OrderRepository
        +submit(order Order) Status
        +defaultCurrency() String$
      }
    }
  }
  Entity <|-- Order
  Order "1" *-- "1..*" LineItem : contains
  Order "many" o-- "1" Status : status
  Repository <|.. OrderRepository : implements
  CheckoutService ..> Repository : queries
  CheckoutService --> Order : validates
  OrderRepository -- Order : persists
  note for Order "An order owns its line items.<br/>Totals must remain consistent."
  note "Repository returns nested generic batches."
  classDef service fill:#fff2cc,stroke:#b8860b,color:#222222
  cssClass "CheckoutService" service
  style Repository fill:#e8f1ff,stroke:#4466aa
  cssClass "Order,LineItem" domain
  classDef domain fill:#f4fbf4,stroke:#447744
